package com.tekwatt.firmware.controller;import com.tekwatt.firmware.dto.*;import com.tekwatt.firmware.entity.*;import com.tekwatt.firmware.service.FirmwareService;import jakarta.validation.Valid;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/v1/firmware")public class FirmwareController{private final FirmwareService service;public FirmwareController(FirmwareService s){service=s;}@PostMapping("/packages")@ResponseStatus(HttpStatus.CREATED)FirmwarePackage createPackage(@Valid@RequestBody FirmwarePackageRequest r){return service.createPackage(r);}@GetMapping("/packages")List<FirmwarePackage>packages(){return service.packages();}@GetMapping("/packages/{id}")FirmwarePackage packageById(@PathVariable UUID id){return service.packageById(id);}@PostMapping("/jobs")@ResponseStatus(HttpStatus.CREATED)FirmwareUpdateJob createJob(@Valid@RequestBody CreateUpdateJobRequest r){return service.createJob(r);}@GetMapping("/jobs")List<FirmwareUpdateJob>jobs(@RequestParam UUID tenantId){return service.jobs(tenantId);}@GetMapping("/jobs/{id}")FirmwareUpdateJob job(@PathVariable UUID id){return service.job(id);}@PatchMapping("/jobs/{id}/status")FirmwareUpdateJob status(@PathVariable UUID id,@Valid@RequestBody UpdateJobStatusRequest r){return service.status(id,r);}@PostMapping("/jobs/{id}/dispatch")FirmwareUpdateJob dispatch(@PathVariable UUID id){return service.dispatch(id);}@PostMapping("/callbacks/status")FirmwareUpdateJob callback(@Valid@RequestBody FirmwareStatusCallback r){return service.callback(r);}}
